import json,hashlib,re
p='/workspace/scratch/volume4/batch389-398.json';x=json.load(open(p))
for page in x['pages']:
 for s in page['paragraphs']:
  s['ar']=s['ar'].replace('كخاطب عشواء','كخابط عشواء')
  s['sha256']=hashlib.sha256(s['ar'].encode()).hexdigest()
lookup={s['id']:s['ar'] for pg in x['pages'] for s in pg['paragraphs']}
for u in x['units']:
 u['ar']=' '.join(lookup[s] for s in u['source_ids'])
 u['ru']=u['ru'].replace('достижение Им искомой близости','достижение близости к Нему').replace('и оно усиливается, пока он не становится','постепенно обретая в этом силу, пока не становится').replace('я же возвысился, пережив Того','я же горжусь переживанием Того').replace('Когда я прищуриваюсь, хотя вовсе не косоглаз.','Когда я делаю вид, что косоглаз, хотя косоглазия у меня нет.').replace('Непосредственное знание дальше от отвлечений, проникновения изъянов и отсутствия невнимательности.','Непосредственное знание дальше от отвлечений и проникновения изъянов, ему не свойственна невнимательность.').replace('Сказано:  ','Сказано:')
 u['draft_status']='self_reviewed'
x['boundary_notes']=[{'printed_page':389,'side':'start','source_id':'v4-p389-01','note':'Открытый начальный фрагмент:388 заканчивается «فتأمل قوله في الإطعام والإسقاء: لوجدت ذلك عندي أي: لوجدت»;389 продолжает «جزاءه وثوابه عندي». Соединить с последним блоком388. Страница388 просмотрена, но не импортирована.'},{'printed_page':398,'side':'end','source_id':'v4-p398-05','note':'Открытый конечный перенос «كما يوطأ» продолжается399 «بساط الملك، وصار ذلك سنة...». Русское «подобно тому как ступают по» также оставлено открытым.399 просмотрена для контекста, но не импортирована.'},{'printed_pages':[389,390],'note':'Слит перенос определения становления واجدا; source_ids сохранены.'},{'printed_pages':[390,391],'note':'Слит перенос определения الوجد после «وهو».'},{'printed_pages':[391,392],'note':'Слит перенос двух мнений о التواجد после «فقالت».'},{'printed_pages':[393,394],'note':'Слита цитата из الصحاح и авторское этимологическое разъяснение.'},{'printed_pages':[395,396],'note':'Слит перенос определения обретения для صاحب الجمع.'},{'printed_pages':[396,397],'note':'Слит перенос иерархии المعرفة/الشهود/الوجود и разъяснения الإشارة.'}]
x['review_notes']=[{'type':'source_collation','pages':list(range(389,399)),'note':'Первый фактический проход: все10 страниц прочитаны по изображениям pdftoppm1800;388 и399 просмотрены исключительно для границ.390,391,392,396 дополнительно просмотрены в увеличении2600px для поэзии и сложных слов. Исправлена ошибка ручного набора «كخاطب» на печатное «كخابط». Современные издательские сноски и маркеры не импортированы.'},{'type':'semantic_back_comparison','pages':list(range(389,399)),'note':'Второй фактический проход: обратная сверка со всеми изображениями. Сохранены пример сокровища389, различия التواجد/الوجد/الوجود389–391, оба мнения и авторское решение391–392, бытие и сущность392–393, полемическое отделение Божественного бытия от дарования бытия393, области действий/имён/сообщений394–395, все3 смысла обретения396–397, все3 ступени таджрида и альтернативные объяснения снятия обуви398. На390–391 переданы2+2 полных поэтических строки и1 цитированное полустишие. Все5 явных аятов394/398 сохранены арабским текстом в{}, повторены тождественно вRU, снабжены переводом смысла и ссылками.'},{'type':'russian_only_reading','pages':list(range(389,399)),'note':'Третий фактический проход: полный русский текст прочитан отдельно. Устранено двусмысленное «достижение Им»389, уточнено فخرت как «горжусь»390, передан смысл искусственного проявления косоглазия391. Печатное396 «وعدم الغفلات» передано отдельной предикацией об отсутствии невнимательности, а не противоречивым «дальше от отсутствия невнимательности». После вычитки выполнена проверка hash/source_ids/объединений/коранических цитат.'},{'type':'uncertainty','pages':[390,391,396],'note':'Синтаксическая шероховатость печатного396 «والضروري أبعد عن الالتفات، وتطرق الآفات، وعدم الغفلات» сохранена вAR;RU трактует последнюю часть как самостоятельное утверждение отсутствия невнимательности.391 печатное «كاتساع فرجة الوجد» сохранено, хотя образ расширения отрады требует редакторской оценки. Поэтические игры корнем وجد390–391 неизбежно теряют часть звучания при русском различении переживания/обретения/бытия; все утверждения и строки переданы. Это самостоятельная проверка переводчика, не независимая человеческая или богословская экспертиза.'}]
used=[]
for pg in x['pages']:
 assert pg['paragraphs']
 for s in pg['paragraphs']:assert hashlib.sha256(s['ar'].encode()).hexdigest()==s['sha256']
for u in x['units']:
 assert u['ar']==' '.join(lookup[s] for s in u['source_ids'])
 assert re.findall(r'\{[^}]*\}',u['ar'])==re.findall(r'\{[^}]*\}',u['ru'])
 used+=u['source_ids']
assert len(used)==len(set(used))==len(lookup)
assert [pg['printed_page'] for pg in x['pages']]==list(range(389,399))
x['completed']=True
open(p,'w').write(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
print({'pages':len(x['pages']),'source_paragraphs':len(lookup),'units':len(x['units']),'quran_fragments':sum(len(re.findall(r'\{[^}]*\}',u['ar'])) for u in x['units']),'completed':True,'all_hashes_links_quotes_valid':True})
